using I=long long;namespace fsys=std::filesystem;
struct V{double l=0,r=0;};V operator+(V a,V b){return{a.l+b.l,a.r+b.r};}V operator*(double s,V a){return{s*a.l,s*a.r};}
struct M{double a,b,c,d;V operator()(V v)const{return{a*v.l+b*v.r,c*v.l+d*v.r};}};
M mix(M x,M y,double w){return{(1-w)*x.a+w*y.a,(1-w)*x.b+w*y.b,(1-w)*x.c+w*y.c,(1-w)*x.d+w*y.d};}
const M J_STEREO{1,0,0,1},J_PINGPONG{.5,.5,0,0},R_STEREO{1,0,0,1},R_PINGPONG{0,1,1,0};
I half_up(double seconds,int rate){return static_cast<I>(std::floor(seconds*rate+.5));}
I fade_frames(char style,int rate){return std::max<I>(1,half_up(style=='B'?.005:.020,rate));}
double limited(double seconds){if(!std::isfinite(seconds))throw std::runtime_error("nonfinite duration");return std::max(.010,std::min(2.000,seconds));}
double weight(I n,I begin,I end){return std::max(0.0,std::min(1.0,double(n-begin)/double(end-begin)));}
std::vector<std::string> split(const std::string&s){std::vector<std::string>r;std::stringstream in(s);std::string x;while(std::getline(in,x,','))r.push_back(x);return r;}
bool safe_id(const std::string&id){if(id.empty())return false;for(unsigned char c:id)if(!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='_'||c=='-'))return false;return true;}
struct Config{std::string id,panel,source,schedule,partition,tap,mutation;char style;bool ping;int rate;double feedback,character;};
Config parse(const std::vector<std::string>&v){if(v.size()!=12)throw std::runtime_error("columns");Config c{v[0],v[1],v[4],v[5],v[7],v[10],v[11],v[2].size()==1?v[2][0]:'?',v[3]=="pingpong",std::stoi(v[6]),std::stod(v[8]),std::stod(v[9])};if(!safe_id(c.id)||std::string("ABC").find(c.style)==std::string::npos)throw std::runtime_error("id/style");if(v[3]!="stereo"&&v[3]!="pingpong")throw std::runtime_error("route");if(c.rate!=44100&&c.rate!=48000&&c.rate!=96000)throw std::runtime_error("rate");if(c.partition!="1"&&c.partition!="64"&&c.partition!="512"&&c.partition!="irregular")throw std::runtime_error("partition");if((c.feedback!=0&&c.feedback!=.5&&c.feedback!=.9)||(c.character!=.5&&c.character!=1)||(c.tap!="pre"&&c.tap!="post"))throw std::runtime_error("gain/tap");if(c.mutation!="none"&&c.mutation!="wrong_side"&&c.mutation!="off_by_one"&&c.mutation!="drop_pending"&&c.mutation!="restart_repeat")throw std::runtime_error("mutation");return c;}
struct Event{std::string control,payload;};using Events=std::map<I,std::vector<Event>>;
Events events_for(const Config&c){Events e;auto at=[&](I n,std::string control,std::string payload){e[n].push_back({control,payload});};auto sec=[&](double t,std::string control,std::string payload){at(half_up(t,c.rate),control,payload);};const I n0=half_up(1,c.rate);const std::string s=c.schedule;
 if(s=="static"){}else if(s=="retarget"){sec(1,"free","0.375");sec(1.005,"free","0.125");sec(1.009,"free","0.300");}
 else if(s=="mode_collision"){sec(1,"division","1");sec(1,"bpm","120");sec(1,"select","sync");sec(1.005,"bpm","90");sec(1.009,"bpm","INVALID_TEMPO_NONFINITE");sec(1.009,"division","0.5");sec(1.009,"division","1");sec(1.020,"free","0.250");sec(1.020,"select","free");sec(1.020,"style",c.style=='C'?"A":"C");}
 else if(s=="timing_return"||s=="timing_repeat"){sec(1,"free","0.375");sec(1.002,"free",s=="timing_return"?"0.250":"0.375");}
 else if(s=="routing"){sec(1,"route","pingpong");sec(1.005,"route","stereo");sec(1.009,"route","pingpong");}
 else if(s=="routing_return"||s=="routing_repeat"){sec(1,"route","pingpong");sec(1.002,"route",s=="routing_return"?"stereo":"pingpong");}
 else if(s=="endpoint"){at(n0,"free","0.375");at(n0,"route","pingpong");at(n0+fade_frames(c.style,c.rate),"free","0.300");at(n0+fade_frames('A',c.rate),"route","stereo");}
 else if(s=="motion"){sec(1,"motion","ramp_0.250_to_0.275_until_1.500");sec(1.5,"motion","hold_0.275");}else throw std::runtime_error("schedule");return e;
}
struct Desired{double free_time=.250,beats=1,bpm=120,last_sync=.500,delay=.250;bool sync=false,tempo_available=true;char style='A';int route=0;};
void apply(Desired&d,const Event&e){if(e.control=="free"){double v=std::stod(e.payload);if(std::isfinite(v))d.free_time=limited(v);}else if(e.control=="division")d.beats=std::stod(e.payload);else if(e.control=="bpm"){d.bpm=e.payload=="INVALID_TEMPO_NONFINITE"?std::numeric_limits<double>::quiet_NaN():std::stod(e.payload);d.tempo_available=std::isfinite(d.bpm)&&d.bpm>0;}else if(e.control=="select")d.sync=e.payload=="sync";else if(e.control=="style")d.style=e.payload.at(0);else if(e.control=="route")d.route=e.payload=="pingpong";else if(e.control!="motion")throw std::runtime_error("event");}
void resolve(Desired&d){if(d.tempo_available)d.last_sync=limited(60*d.beats/d.bpm);d.delay=d.sync?d.last_sync:limited(d.free_time);}
struct Timing{double committed=.250,from=.250,target=.250,pending_delay=0;char committed_style='A',target_style='A',pending_style='A';I begin=0,end=0;bool active=false,pending=false;};
struct Routing{int committed=0,from=0,target=0,pending_mode=0;I begin=0,end=0;bool active=false,pending=false;};
double moving_position(const Timing&t,I n){if(!t.active)return t.committed;double a=weight(n,t.begin,t.end);return(1-a)*t.from+a*t.target;}
double route_position(const Routing&r,I n){if(!r.active)return double(r.committed);double a=weight(n,r.begin,r.end);return(1-a)*r.from+a*r.target;}
void start(Timing&t,I n,double from,const Desired&d,int rate){t.from=from;t.target=d.delay;t.target_style=d.style;t.begin=n;t.end=n+fade_frames(d.style,rate);t.active=true;t.pending=false;}
void arbitrate(Timing&t,I n,const Desired&d,int rate){if(t.active){const bool same=t.target==d.delay&&t.target_style==d.style;if(same){t.pending=false;return;}if(t.target_style!='C'){t.pending=true;t.pending_delay=d.delay;t.pending_style=d.style;}else{double position=moving_position(t,n);start(t,n,position,d,rate);}}else if(t.committed!=d.delay||t.committed_style!=d.style)start(t,n,t.committed,d,rate);else t.pending=false;}
void arbitrate(Routing&r,I n,const Desired&d,int rate){if(r.active){if(r.target==d.route)r.pending=false;else{r.pending=true;r.pending_mode=d.route;}}else if(r.committed!=d.route){r.from=r.committed;r.target=d.route;r.begin=n;r.end=n+fade_frames('A',rate);r.active=true;r.pending=false;}else r.pending=false;}
struct Step{I n;Desired desired;Timing timing;Routing routing;};
std::vector<Step> make_plan(const Config&c,const Events&events){Desired d;d.style=c.style;d.route=c.ping?1:0;Timing t;t.committed_style=t.target_style=c.style;Routing r;r.committed=r.from=r.target=d.route;std::vector<Step>plan;const I last=20LL*c.rate-1;I n=0;for(;;){if(t.active&&n==t.end){t.committed=t.target;t.committed_style=t.target_style;t.active=false;}if(r.active&&n==r.end){r.committed=r.target;r.active=false;}auto ev=events.find(n);if(ev!=events.end())for(const auto&x:ev->second)apply(d,x);resolve(d);if(c.schedule!="motion")arbitrate(t,n,d,c.rate);arbitrate(r,n,d,c.rate);plan.push_back({n,d,t,r});if(n==last)break;I next=last;auto following=events.upper_bound(n);if(following!=events.end())next=std::min(next,following->first);if(t.active)next=std::min(next,t.end);if(r.active)next=std::min(next,r.end);if(next<=n)throw std::runtime_error("plan nonadvance");n=next;}return plan;}
struct Read{double old_delay,new_delay,alpha;};
Read read_for(const Config&c,const Step&s,I n){if(c.schedule=="motion"){const double time=double(n)/c.rate;const double d=time<1?.250:time<1.5?.250+.025*(time-1)/.5:.275;return{d,d,0};}const Timing&t=s.timing;if(!t.active)return{t.committed,t.committed,0};double a=weight(n,t.begin,t.end);if(t.target_style=='C'){double d=(1-a)*t.from+a*t.target;return{d,d,a};}return{t.from,t.target,a};}
V source_for(const Config&c,I n){const std::string&s=c.source;if(s.rfind("impulse_",0)==0){if(n!=0)return{};if(s=="impulse_center")return{.125,.125};if(s=="impulse_left")return{.125,0};if(s=="impulse_right")return{0,.125};if(s=="impulse_stereo")return{.125,-.0625};if(s=="impulse_antiphase")return{.125,-.125};throw std::runtime_error("impulse");}const double time=double(n)/c.rate,pi=std::acos(-1.0);double v=0;if(s=="step"){if(time<2)v=.125;}else if(s=="sine"){if(time<2)v=.125*std::sin(2*pi*1000*double(n)/c.rate);}else if(s=="pluck"){for(double event_time:{0.0,1.0}){double tau=time-event_time;if(tau>=0&&tau<1)v+=.04*std::exp(-8*tau)*(std::sin(2*pi*220*tau)+std::sin(2*pi*330*tau)+std::sin(2*pi*440*tau));}}else throw std::runtime_error("source");return{v,v};}
V history_read(const std::vector<V>&history,I n,double seconds,int rate){double absolute=double(n)-seconds*rate;I lower=static_cast<I>(std::floor(absolute));double fraction=absolute-double(lower);auto stored=[&](I k)->V{if(k<0)return{};if(k>=n)throw std::runtime_error("noncausal read");return history.at(static_cast<std::size_t>(k));};return(1-fraction)*stored(lower)+fraction*stored(lower+1);}
struct RawWriter{std::ofstream out;std::vector<char>buffer;explicit RawWriter(const fsys::path&p):out(p,std::ios::binary){static_assert(sizeof(double)==8,"binary64");static_assert(std::numeric_limits<double>::is_iec559,"IEEE754");if(!out)throw std::runtime_error("raw open");buffer.reserve(65536);}void scalar(double x){std::uint64_t bits;std::memcpy(&bits,&x,8);for(int b=0;b<8;++b)buffer.push_back(static_cast<char>((bits>>(8*b))&255));if(buffer.size()>=65536)flush();}void flush(){if(!buffer.empty()){out.write(buffer.data(),static_cast<std::streamsize>(buffer.size()));buffer.clear();}if(!out)throw std::runtime_error("raw write");}void finish(){flush();out.close();}};
const char* mode(int m){return m?"pingpong":"stereo";}
void trace_header(std::ostream&o){o<<"sample,reason,desired_delay,desired_style,read_old,read_new,timing_alpha,timing_active,timing_destination,timing_destination_style,timing_pending,timing_pending_delay,timing_pending_style,committed_delay,committed_style,route_weight,route_active,route_destination,route_pending,route_pending_mode,committed_route,tempo_available\n";}
void trace_row(std::ostream&o,const Config&c,const Step&s,I n){const auto&t=s.timing;const auto&r=s.routing;Read q=read_for(c,s,n);o<<n<<",audit,"<<s.desired.delay<<','<<s.desired.style<<','<<q.old_delay<<','<<q.new_delay<<','<<q.alpha<<','<<int(t.active)<<','<<(t.active?t.target:t.committed)<<','<<(t.active?t.target_style:t.committed_style)<<','<<int(t.pending)<<','<<(t.pending?t.pending_delay:0)<<','<<(t.pending?std::string(1,t.pending_style):"none")<<','<<t.committed<<','<<t.committed_style<<','<<route_position(r,n)<<','<<int(r.active)<<','<<mode(r.active?r.target:r.committed)<<','<<int(r.pending)<<','<<(r.pending?mode(r.pending_mode):"none")<<','<<mode(r.committed)<<','<<int(s.desired.tempo_available)<<'\n';}
void render(const Config&c,const fsys::path&dir,std::ostream&metrics){Events events=events_for(c);auto plan=make_plan(c,events);const I frames=20LL*c.rate;std::set<I>audits{0,frames-1};for(const auto&s:plan)if(s.n>0&&s.n<frames-1)for(I offset:{-1LL,0LL,1LL})if(s.n+offset>=0&&s.n+offset<frames)audits.insert(s.n+offset);std::ofstream trace(dir/(c.id+".trace.csv"));if(!trace)throw std::runtime_error("trace open");trace<<std::setprecision(17);trace_header(trace);RawWriter raw(dir/(c.id+".f64"));std::vector<V>history(static_cast<std::size_t>(frames));std::size_t cursor=0;double state_peak=0,output_peak=0,left=0,right=0,fold=0;for(I n=0;n<frames;++n){while(cursor+1<plan.size()&&plan[cursor+1].n<=n)++cursor;const Step&s=plan[cursor];const Read q=read_for(c,s,n);V a=history_read(history,n,q.old_delay,c.rate);if(s.timing.active&&s.timing.target_style!='C'&&c.schedule!="motion")a=(1-q.alpha)*a+q.alpha*history_read(history,n,q.new_delay,c.rate);V processed=c.character*a;double w=route_position(s.routing,n);V stored=mix(J_STEREO,J_PINGPONG,w)(source_for(c,n))+c.feedback*mix(R_STEREO,R_PINGPONG,w)(processed);V y=c.tap=="pre"?a:processed;if(!std::isfinite(stored.l)||!std::isfinite(stored.r)||!std::isfinite(y.l)||!std::isfinite(y.r))throw std::runtime_error(c.id+" nonfinite "+std::to_string(n));state_peak=std::max({state_peak,std::abs(stored.l),std::abs(stored.r)});output_peak=std::max({output_peak,std::abs(y.l),std::abs(y.r)});if(state_peak>1.25001)throw std::runtime_error(c.id+" state bound");history[static_cast<std::size_t>(n)]=stored;raw.scalar(y.l);raw.scalar(y.r);left+=y.l*y.l;right+=y.r*y.r;double mono=(y.l+y.r)/2;fold+=mono*mono;if(audits.count(n))trace_row(trace,c,s,n);}raw.finish();trace.close();if(!trace)throw std::runtime_error("trace write");metrics<<c.id<<','<<frames<<",1,"<<state_peak<<','<<output_peak<<','<<left<<','<<right<<','<<fold<<'\n';metrics.flush();if(!metrics)throw std::runtime_error("metrics write");}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("usage: oracle manifest.csv outputDirectory");std::ifstream manifest(argv[1]);if(!manifest)throw std::runtime_error("manifest open");std::string line;if(!std::getline(manifest,line))throw std::runtime_error("empty manifest");if(!line.empty()&&line.back()=='\r')line.pop_back();if(line!="id,panel,style,mode,source,schedule,rate,partition,feedback,char_gain,tap,mutation")throw std::runtime_error("header");std::vector<Config>rows;std::set<std::string>ids;while(std::getline(manifest,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();if(line.empty())continue;Config c=parse(split(line));if(!ids.insert(c.id).second)throw std::runtime_error("duplicate id");rows.push_back(c);}fsys::path dir(argv[2]);if(fsys::exists(dir)&&(!fsys::is_directory(dir)||fsys::directory_iterator(dir)!=fsys::directory_iterator{}))throw std::runtime_error("refusing nonempty output; preserve attempt");fsys::create_directories(dir);std::ofstream metrics(dir/"metrics.csv");if(!metrics)throw std::runtime_error("metrics open");metrics<<std::setprecision(17)<<"id,frames,finite,state_peak,output_peak,left_energy,right_energy,fold_energy\n";std::size_t done=0;for(const Config&c:rows){render(c,dir,metrics);++done;if(done%10==0||done==rows.size())std::cout<<"oracle "<<done<<'/'<<rows.size()<<" complete\n"<<std::flush;}return 0;}catch(const std::exception&e){std::cerr<<"oracle STOP: "<<e.what()<<'\n';return 1;}}
